WITH country_segments AS (SELECT transactions_1k.gasstationid, gasstations.country, customers.segment, transactions_1k.amount FROM transactions_1k JOIN gasstations ON transactions_1k.gasstationid = gasstations.gasstationid JOIN customers ON transactions_1k.customerid = customers.customerid) SELECT country, segment, COUNT(*) as transaction_count, SUM(amount) as total_value FROM country_segments GROUP BY country, segment ORDER BY total_value DESC;
